def buscar(arr, x):
    izq, der = 0, len(arr) - 1
    while izq <= der:
        medio = (izq + der) // 2
        if arr[medio] == x:
            return medio
        if arr[medio] < x:
            izq = medio + 1
        else:
            der = medio - 1
    return -1

print(buscar([2, 5, 8, 12, 16, 23, 38, 56, 72, 91], 23))

